public long Chunk(ByteBuffer buffer) throws IOException {
    if (endOfFile) {
        return -1;
    }
    final int remainingBytes = data.length - cursor;
    if (remainingBytes <= buffer.capacity()) {
        buffer.put(data, cursor, remainingBytes);
        endOfFile = true;
        return remainingBytes;
    } else {
        buffer.put(data, cursor, buffer.capacity());
        cursor += buffer.capacity();
        return buffer.capacity();
    }
}

