def chunk(self, size=None):
    if self.pos >= self.total:
        return ''
    if size is None or size < 0 or size + self.pos >= self.total:
        chunk = self.file.read(self.total - self.pos)
        self.pos = self.total
        return chunk
    self.pos += size
    return self.file.read(size)

